using namespace std;

class FastInput {
    static const int BUFFER_SIZE = 1 << 13;
    char buffer[BUFFER_SIZE];
    int length = 0;
    int offset = 0;

    int read() {
        if (offset >= length) {
            length = static_cast<int>(fread(buffer, 1, BUFFER_SIZE, stdin));
            offset = 0;
            if (length == 0) return -1;
        }
        return static_cast<unsigned char>(buffer[offset++]);
    }

public:
    int readInt() {
        int c;
        do {
            c = read();
        } while (c >= 0 && c <= 32);

        int sign = 1;
        if (c == '+' || c == '-') {
            sign = (c == '-') ? -1 : 1;
            c = read();
        }

        int value = 0;
        while (c >= '0' && c <= '9') {
            value = value * 10 + c - '0';
            c = read();
        }
        return value * sign;
    }
};

class Modular {
    int mod;

public:
    explicit Modular(int mod) : mod(mod) {}

    int add(int a, int b) const {
        int result = a + b;
        if (result >= mod) result -= mod;
        return result;
    }

    int multiply(int a, int b) const {
        return static_cast<int>(static_cast<int64_t>(a) * b % mod);
    }
};

int main() {
    FastInput in;
    const Modular mod(1000000007);

    int n = in.readInt();
    int m = in.readInt();

    vector<array<int, 2>> musics(n);
