    int c2 = counts[2];
    int c3 = counts[3];

    const size_t d2 = static_cast<size_t>(c2 + 1);
    const size_t d3 = static_cast<size_t>(c3 + 1);

    auto stateIndex = [=](int i, int j, int k) -> size_t {
        return (static_cast<size_t>(i) * d2 + j) * d3 + k;
    };

    size_t stateCount = static_cast<size_t>(c1 + 1) * d2 * d3;
    vector<int> comp(stateCount * 4, 0);

    auto compIndex = [&](int i, int j, int k, int lastType) -> size_t {
        return stateIndex(i, j, k) * 4 + lastType;
    };

    for (int i = 0; i <= c1; ++i) {
        for (int j = 0; j <= c2; ++j) {
            for (int k = 0; k <= c3; ++k) {
                for (int t = 0; t < 4; ++t) {
                    size_t current = compIndex(i, j, k, t);

                    if (i == 0 && j == 0 && k == 0) {
                        comp[current] = 1;
                        continue;
                    }

                    if (i > 0 && t != 1) {
                        comp[current] = mod.add(
                            comp[current],
                            mod.multiply(comp[compIndex(i - 1, j, k, 1)], i)
                        );
                    }

                    if (j > 0 && t != 2) {
                        comp[current] = mod.add(
                            comp[current],
                            mod.multiply(comp[compIndex(i, j - 1, k, 2)], j)
                        );
                    }

                    if (k > 0 && t != 3) {
                        comp[current] = mod.add(
                            comp[current],
                            mod.multiply(comp[compIndex(i, j, k - 1, 3)], k)
                        );
                    }
                }
            }
        }
    }

    const size_t timeSize = static_cast<size_t>(m + 1);
    vector<int> last(stateCount * timeSize, 0);
    vector<int> next(stateCount * timeSize, 0);

    auto dpIndex = [&](int i, int j, int k, int time) -> size_t {
        return stateIndex(i, j, k) * timeSize + time;
    };

    last[dpIndex(0, 0, 0, 0)] = 1;

    int t1 = 0;
    int t2 = 0;
    int t3 = 0;

    for (const auto& music : musics) {
        int duration = music[0];
        int type = music[1];

        if (type == 1) {
            ++t1;
        } else if (type == 2) {
            ++t2;
        } else {
            ++t3;
        }

        for (int i = 0; i <= t1; ++i) {
            for (int j = 0; j <= t2; ++j) {
                for (int k = 0; k <= t3; ++k) {
                    for (int time = 0; time <= m; ++time) {
                        size_t current = dpIndex(i, j, k, time);
                        next[current] = last[current];

                        if (time < duration) continue;

                        if (type == 1 && i > 0) {
                            next[current] = mod.add(
                                next[current],
                                last[dpIndex(i - 1, j, k, time - duration)]
                            );
                        } else if (type == 2 && j > 0) {
                            next[current] = mod.add(
                                next[current],
                                last[dpIndex(i, j - 1, k, time - duration)]
                            );
                        } else if (type == 3 && k > 0) {
                            next[current] = mod.add(
                                next[current],
                                last[dpIndex(i, j, k - 1, time - duration)]
                            );
                        }
                    }
                }
            }
        }

        last.swap(next);
    }

    int answer = 0;

    for (int i = 0; i <= c1; ++i) {
        for (int j = 0; j <= c2; ++j) {
            for (int k = 0; k <= c3; ++k) {
                answer = mod.add(
                    answer,
                    mod.multiply(
                        last[dpIndex(i, j, k, m)],
                        comp[compIndex(i, j, k, 0)]
                    )
                );
            }
        }
    }

    cout << answer << '\n';
    return 0;
}

